    pub(super) fn resolve_confirm_delete_agent(&mut self, confirm: bool) -> bool {
        let (session_id, delete_worktree) = match &self.prompt {
            PromptState::ConfirmDeleteAgent {
                session_id,
                delete_worktree,
                ..
            } => (session_id.clone(), *delete_worktree),
            _ => return false,
        };
        self.prompt = PromptState::None;
        if confirm {
            // Dispatches git work to a worker when needed, so the UI stays
            // responsive. Errors arrive asynchronously via
            // `WorkerEvent::WorktreeRemoveCompleted`.
            self.begin_delete_session(&session_id, delete_worktree);
        }
        false
    }

    pub(super) fn resolve_confirm_delete_terminal(&mut self, confirm: bool) -> bool {
        let terminal_id = match &self.prompt {
            PromptState::ConfirmDeleteTerminal { terminal_id, .. } => terminal_id.clone(),
            _ => return false,
        };
        self.prompt = PromptState::None;
        if confirm {
            self.do_delete_terminal(&terminal_id);
        }
        false
    }

    pub(super) fn resolve_confirm_close_tab(&mut self, confirm: bool) -> bool {
        let (session_id, tab_id, is_main) = match &self.prompt {
            PromptState::ConfirmCloseTab {
                session_id,
                tab_id,
                is_main,
                ..
            } => (session_id.clone(), tab_id.clone(), *is_main),
            _ => return false,
        };
        self.prompt = PromptState::None;
        if !confirm {
            return false;
        }
        if is_main {
            // Closing the session-slot tab (which has no row) stops just that
            // tab's provider; the agent detaches only when it was the last live
            // tab (kill_runtime_targets handles the detach-if-last). Other tabs
            // keep running and the agent stays Active.
            self.kill_runtime_targets(&[RuntimeTargetId::Agent(session_id.clone())]);
            // Prefer a live sibling tab so the user lands on something
            // running; fall back to the now-dormant session-slot tab only
            // when nothing else is live.
            let target = self
                .engine
                .first_live_tab(&session_id)
                .unwrap_or_else(|| session_id.clone());
            self.set_focused_tab(&session_id, &target);
            if self.engine.any_tab_active(&session_id) {
                self.set_info("Tab closed. The agent's other tabs are still running.".to_string());
            } else {
                self.set_info(
                    "Closed the last tab, so the agent detached. It stays in Projects and can be reopened at any time.".to_string(),
                );
            }
        } else {
            match self.engine.close_tab(&session_id, &tab_id) {
                // The core `CloseTabOutcome.detached` is authoritative; this
                // branch's messaging does not distinguish detach, so it is
                // ignored here (the session-slot close path above reports it).
                Ok(_) => {
                    // Prefer a live sibling tab so the user lands on something
                    // running; fall back to the session-slot tab only when
                    // nothing else is live. This also resets the snapshot so
                    // the target tab's PTY renders immediately, and keeps the
                    // next ExitInteractive (activate) from relaunching a
                    // dormant tab.
                    let target = self
                        .engine
                        .first_live_tab(&session_id)
                        .unwrap_or_else(|| session_id.clone());
                    self.set_focused_tab(&session_id, &target);
                    self.rebuild_left_items();
                    self.set_info("Tab closed.".to_string());
                }
                Err(e) => {
                    self.set_error(format!("Could not close the tab: {e}"));
                }
            }
        }
        false
    }

    pub(super) fn resolve_confirm_kill_running(&mut self, confirm: bool) -> bool {
        let confirm_prompt = match &self.prompt {
            PromptState::ConfirmKillRunning(confirm_prompt) => confirm_prompt.clone(),
            _ => return false,
        };
        if !confirm {
            self.prompt = PromptState::KillRunning(confirm_prompt.previous);
            self.set_info(
                "Kill cancelled. Your running agents and companion terminals are unchanged.",
            );
            return false;
        }

        self.prompt = PromptState::None;
        let requested = confirm_prompt.target_ids.len();
        let (agents, terminals) = self.kill_runtime_targets(&confirm_prompt.target_ids);
        let killed = agents + terminals;
        let already_gone = requested.saturating_sub(killed);
        if killed == 0 {
            self.set_warning(
                "The selected agents or terminals were already gone, so there was nothing left to kill. Refresh Kill Running if you want to review the current runtime list.",
            );
            return false;
        }

        let mut pieces = Vec::new();
        if agents > 0 {
            pieces.push(format!(
                "{agents} agent{}",
                if agents == 1 { "" } else { "s" }
            ));
        }
        if terminals > 0 {
            pieces.push(format!(
                "{terminals} terminal{}",
                if terminals == 1 { "" } else { "s" }
            ));
        }
        if already_gone > 0 {
            self.set_warning(format!(
                "Killed {}. {} selected runtime{} were already gone. In-progress CLI work was stopped, but the worktree files are still available for review or relaunch.",
                pieces.join(" and "),
                already_gone,
                if already_gone == 1 { "" } else { "s" }
            ));
        } else {
            self.set_info(format!(
                "Killed {}. In-progress CLI work was stopped, but the worktree files are still available for review or relaunch.",
                pieces.join(" and ")
            ));
        }
        false
    }

    pub(super) fn resolve_confirm_quit(&mut self, confirm: bool) -> bool {
        if matches!(self.prompt, PromptState::ConfirmQuit { .. }) {
            self.prompt = PromptState::None;
        }
        confirm
    }

    pub(super) fn resolve_confirm_discard_file(&mut self, confirm: bool) -> bool {
        let file_path = match &self.prompt {
            PromptState::ConfirmDiscardFile { file_path, .. } => file_path.clone(),
            _ => return false,
        };
        self.prompt = PromptState::None;
        if confirm && let Some(session) = self.selected_session() {
            let worktree = PathBuf::from(&session.worktree_path);
            // Re-classify against LIVE git status at confirm time, then act on that
            // fresh flag, so the delete-vs-restore decision and the destructive
            // action agree with the worktree as it is NOW (not as it was when the
            // prompt opened). This closes a data-loss window: a file that was
            // untracked at prompt-open but became tracked before confirm would
            // otherwise be deleted outright instead of restored from HEAD.
            let is_untracked = match git::discard_classify(&worktree, &file_path) {
                Ok(u) => u,
                Err(e) => {
                    // The live check refused (now staged, or nothing left to
                    // discard). Surface it and leave the file untouched.
                    self.set_error(format!("Discard failed: {e}"));
                    return false;
                }
            };
            let reaction = self.engine.apply(Command::DiscardFile {
                worktree_path: worktree,
                path: file_path,
                is_untracked,
            });
            match reaction {
                Ok(reaction) => {
                    self.apply_reaction(reaction);
                    self.reload_changed_files();
                }
                Err(e) => self.set_error(format!("Discard failed: {e}")),
            }
        }
        false
    }

    /// Resolve the "create initial commit" prompt shown when adding a repo with
    /// no commits. On confirm: dispatch the commit to a background worker (which
    /// registers the project on completion). On cancel: leave the repo and
    /// workspace untouched. Always returns `false` (never quits).
    pub(crate) fn resolve_confirm_create_initial_commit(&mut self, confirm: bool) -> bool {
        let (path, name) = match &self.prompt {
            PromptState::ConfirmCreateInitialCommit { path, name, .. } => {
                (path.clone(), name.clone())
            }
            _ => return false,
        };
        self.prompt = PromptState::None;
        if !confirm {
            self.set_info(
                "Add cancelled. A project needs at least one commit — run \"git commit\" (or re-add and confirm) to create the initial commit.",
            );
            return false;
        }
        // The commit runs on a worker (it can invoke slow filesystem/lock work);
        // completion posts `InitialCommitCreated`, whose reaction registers the
        // project. Keeps the UI thread free per the CLAUDE.md workers tenet.
        self.dispatch_create_initial_commit(path, name);
        false
    }

    /// Resolve the adopt-a-folder prompt shown when adding a plain folder that
    /// is not a git repository. On confirm: dispatch git init + seed + initial
    /// commit to a background worker (which registers the project on
    /// completion). On cancel: leave the folder untouched and restore the
    /// project browser. Always returns `false` (never quits).
    pub(crate) fn resolve_confirm_init_repo(&mut self, confirm: bool) -> bool {
        let (path, name, return_prompt) =
            match std::mem::replace(&mut self.prompt, PromptState::None) {
                PromptState::ConfirmInitRepo {
                    path,
                    name,
                    return_prompt,
                    ..
                } => (path, name, return_prompt),
                other => {
                    self.prompt = other;
                    return false;
                }
            };
        if !confirm {
            // Restore the browser exactly as the user left it (location,
            // typed path), the AddProjectFailed pattern; never rebuild it at
            // the start directory.
            self.prompt = *return_prompt;
            return false;
        }
        self.dispatch_init_repo(path, name);
        false
    }

    fn resolve_confirm_non_default_branch(&mut self) -> bool {
        let (action, branch, checkout_default, default_branch) = match &self.prompt {
            PromptState::ConfirmNonDefaultBranch {
                action,
                current_branch,
                kind,
                checkout_default,
                ..
            } => {
                let default_branch = match kind {
                    BranchWarningKind::Known { default_branch } => Some(default_branch.clone()),
                    BranchWarningKind::Heuristic => None,
                };
                (
                    action.clone(),
                    current_branch.clone(),
                    *checkout_default && default_branch.is_some(),
                    default_branch,
                )
            }
            _ => return false,
        };
        self.prompt = PromptState::None;
        if checkout_default {
            // Safe: `checkout_default` is only true when `default_branch` is `Some`.
            let target = default_branch.expect("checkout_default implies known default branch");
            let reason = match action {
                NonDefaultBranchAction::AddProject { .. } => "before adding the project",
                NonDefaultBranchAction::CheckoutProjectDefault { .. } => "for the selected project",
            };
            self.dispatch_non_default_branch_checkout(action, target, reason.to_string(), None);
        } else {
            match action {
                NonDefaultBranchAction::AddProject {
                    path,
                    name,
                    leading_branch,
                } => {
                    if let Err(e) = self.finish_add_project(path, name, branch, leading_branch) {
                        self.set_error(format!("{e:#}"));
                    }
                }
                NonDefaultBranchAction::CheckoutProjectDefault { .. } => {
                    self.set_error("Check out the default branch before retrying.");
                }
            }
        }
        false
    }

    pub(super) fn resolve_confirm_use_existing_branch(&mut self, confirm: bool) -> bool {
        let old_prompt = std::mem::replace(&mut self.prompt, PromptState::None);
        let PromptState::ConfirmUseExistingBranch {
            mut request,
            branch_name,
            ..
        } = old_prompt
        else {
            return false;
        };
        if !confirm {
            return false;
        }
        if let CreateAgentRequest::NewProject {
            use_existing_branch,
            ..
        }
        | CreateAgentRequest::PullRequest {
            use_existing_branch,
            ..
        } = &mut request
        {
            *use_existing_branch = true;
        }
        let msg = match &request {
            CreateAgentRequest::NewProject { project, .. }
            | CreateAgentRequest::PullRequest { project, .. } => {
                format!(
                    "Attaching to existing branch \"{branch_name}\" for project \"{}\" and launching a fresh session...",
                    project.name
                )
            }
            CreateAgentRequest::ForkSession { .. }
            | CreateAgentRequest::ExistingManagedWorktree { .. }
            | CreateAgentRequest::ForkExternalWorktree { .. } => unreachable!(),
        };
        if let Err(e) = self.dispatch_create_agent_request(request, msg) {
            self.set_error(format!("{e:#}"));
        }
        false
    }

    fn set_rename_cursor_from_mouse(&mut self, column: u16) {
        let input_area = match self.overlay_layout.active {
            OverlayMouseLayout::RenameSession { input, .. } => input,
            _ => return,
        };
        if let PromptState::RenameSession { input, focus, .. } = &mut self.prompt {
            // The single-line renderer pads by one leading space.
            input.cursor = cursor_from_single_line_position(&input.text, input_area, 1, column);
            *focus = RenameSessionFocus::Input;
        }
    }

