    fn init_git_repo_with_modified_file(
        app: &App,
        relative_path: &str,
        original: &str,
        updated: &str,
    ) {
        let worktree = std::path::Path::new(&app.engine.sessions[0].worktree_path);
        std::fs::create_dir_all(worktree).expect("worktree dir");

        Command::new("git")
            .args(["init"])
            .current_dir(worktree)
            .output()
            .expect("git init");
        Command::new("git")
            .args(["config", "user.email", "test@example.com"])
            .current_dir(worktree)
            .output()
            .expect("git email");
        Command::new("git")
            .args(["config", "user.name", "Test User"])
            .current_dir(worktree)
            .output()
            .expect("git name");

        let file_path = worktree.join(relative_path);
        if let Some(parent) = file_path.parent() {
            std::fs::create_dir_all(parent).expect("file parent");
        }
        std::fs::write(&file_path, original).expect("write original");
        Command::new("git")
            .args(["add", relative_path])
            .current_dir(worktree)
            .output()
            .expect("git add");
        Command::new("git")
            .args(["commit", "-m", "initial"])
            .current_dir(worktree)
            .output()
            .expect("git commit");

        std::fs::write(&file_path, updated).expect("write updated");
    }

    #[test]
    fn refresh_selected_project_blocks_repeat_presses_while_pull_is_running() {
        let mut app = test_app(default_bindings());
        // Flat model: project actions resolve the selected AGENT's project, so
        // select the seeded session's row rather than a (now-absent) project header.
        app.selected_left = app
            .left_items()
            .iter()
            .position(|i| matches!(i, LeftItem::Session(_)))
            .expect("session row");

        app.refresh_selected_project()
            .expect("start project refresh");
        app.refresh_selected_project()
            .expect("repeat refresh should not error");

        let repo_path = app.engine.projects[0].path.clone();
        assert!(app.engine.is_in_flight(&InFlightKey::Pull(repo_path)));
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Warning);
        assert!(app.status.text().contains("already in progress"));
    }

    #[test]
    fn project_pull_completion_clears_in_flight_guard() {
        let mut app = test_app(default_bindings());
        let repo_path = app.engine.projects[0].path.clone();
        app.engine
            .mark_in_flight(InFlightKey::Pull(repo_path.clone()));

        app.engine
            .worker_tx
            .send(WorkerEvent::PullCompleted {
                repo_path: repo_path.clone(),
                target: PullTarget::Project {
                    project_id: app.engine.projects[0].id.clone(),
                    project_name: app.engine.projects[0].name.clone(),
                    leading_branch: app.engine.projects[0].leading_branch.clone(),
                },
                result: Ok(dux_core::worker::PullOutcome::Pulled {
                    current_branch: Some("feature/demo".to_string()),
                }),
                status: dux_core::engine::ResolvedFinal::new(
                    format!("pull-project:{}", app.engine.projects[0].id),
                    dux_core::engine::Final::info(format!(
                        "Refreshed project \"{}\". Local branch is up to date with remote.",
                        app.engine.projects[0].name
                    )),
                ),
            })
            .expect("queue worker event");

        app.drain_events();

        assert!(!app.engine.is_in_flight(&InFlightKey::Pull(repo_path)));
        assert_eq!(app.engine.projects[0].current_branch, "feature/demo");
        assert_eq!(
            app.engine.projects[0].branch_status,
            ProjectBranchStatus::NotLeading
        );
        assert_eq!(app.status.tone(), crate::statusline::StatusTone::Info);
    }

