    #[test]
    fn name_sort_mode_orders_display_without_mutating_sessions() {
        // The TUI's name sort is a DISPLAY ordering only: setting
        // config.ui.agent_sort = "name" and rebuilding orders left_items()
        // alphabetically while engine.sessions stays in its incoming order.
        let mut app = test_app(default_bindings());
        let now = Utc::now();
        let project_id = app.engine.projects[0].id.clone();
        let project_path = app.engine.projects[0].path.clone();

        app.engine.sessions.clear();
        for name in ["charlie", "alpha", "bravo"] {
            let session = AgentSession {
                id: format!("session-{name}"),
                project_id: project_id.clone(),
                project_path: Some(project_path.clone()),
                provider: ProviderKind::from_str("codex"),
                source_branch: "main".to_string(),
                branch_name: name.to_string(),
                initial_branch: name.to_string(),
                worktree_path: app
                    .engine
                    .paths
                    .worktrees_root
                    .join(name)
                    .display()
                    .to_string(),
                title: None,
                started_providers: Vec::new(),
                desired_running: false,
                auto_reopen_enabled: true,
                status: SessionStatus::Active,
                created_at: now,
                updated_at: now,
                last_focused_tab: None,
            };
            app.engine.session_store.upsert_session(&session).unwrap();
            app.engine.sessions.push(session);
        }

        app.engine.config.ui.agent_sort = "name".to_string();
        app.rebuild_left_items();

        // The DISPLAY order (left_items) is alphabetical.
        let displayed: Vec<String> = app
            .left_items()
            .iter()
            .filter_map(|item| match item {
                LeftItem::Session(i) => Some(app.engine.sessions[*i].branch_name.clone()),
                _ => None,
            })
            .collect();
        assert_eq!(displayed, vec!["alpha", "bravo", "charlie"]);

        // engine.sessions is UNTOUCHED: still the incoming (charlie, alpha, bravo)
        // order. The TUI never mutates the stored order for a display sort.
        let in_memory: Vec<String> = app
            .engine
            .sessions
            .iter()
            .map(|s| s.branch_name.clone())
            .collect();
        assert_eq!(in_memory, vec!["charlie", "alpha", "bravo"]);
    }

    /// Build an Active agent session in the given project with a non-existent
    /// worktree (so a reconnect triggered by Enter fails safely without spawning a
    /// PTY). Used by the agent-filter tests below.
    fn filter_test_session(
        id: &str,
        branch: &str,
        project_id: &str,
        now: chrono::DateTime<Utc>,
    ) -> AgentSession {
        AgentSession {
            id: id.to_string(),
            project_id: project_id.to_string(),
            project_path: Some(format!("/tmp/does-not-exist/{project_id}")),
            provider: ProviderKind::from_str("codex"),
            source_branch: "main".to_string(),
            branch_name: branch.to_string(),
            initial_branch: branch.to_string(),
            worktree_path: format!("/tmp/does-not-exist/{id}"),
            title: None,
            started_providers: Vec::new(),
            desired_running: false,
            auto_reopen_enabled: true,
            status: SessionStatus::Active,
            created_at: now,
            updated_at: now,
            last_focused_tab: None,
        }
    }

    fn filtered_branches(app: &App) -> Vec<String> {
        app.left_items()
            .iter()
            .filter_map(|item| match item {
                LeftItem::Session(i) => Some(app.engine.sessions[*i].branch_name.clone()),
                _ => None,
            })
            .collect()
    }

    #[test]
    fn slash_opens_filter_mode_and_typing_narrows_the_agent_list() {
        let mut app = test_app(default_bindings());
        let now = Utc::now();
        let project_id = app.engine.projects[0].id.clone();
        app.engine.sessions.clear();
        for branch in ["api", "web", "auth"] {
            app.engine.sessions.push(filter_test_session(
                &format!("session-{branch}"),
                branch,
                &project_id,
                now,
            ));
        }
        app.rebuild_left_items();
        app.focus = FocusPane::Left;
        app.left_section = LeftSection::Projects;

        // `/` (the Left-scope FilterAgents binding) enters filter mode.
        app.handle_key(KeyEvent::new(KeyCode::Char('/'), KeyModifiers::NONE))
            .unwrap();
        assert!(app.agent_filter.is_some(), "slash should open filter mode");

        // Typing routes into the query (letters are input, not hotkeys) and
        // live-filters: "au" matches only the "auth" branch.
        for c in ['a', 'u'] {
            app.handle_key(KeyEvent::new(KeyCode::Char(c), KeyModifiers::NONE))
                .unwrap();
        }
        assert_eq!(app.agent_filter.as_ref().unwrap().text, "au");
        assert_eq!(filtered_branches(&app), vec!["auth".to_string()]);

        // Backspacing to an empty query restores the full list.
        app.handle_key(KeyEvent::new(KeyCode::Backspace, KeyModifiers::NONE))
            .unwrap();
        app.handle_key(KeyEvent::new(KeyCode::Backspace, KeyModifiers::NONE))
            .unwrap();
        assert_eq!(app.agent_filter.as_ref().unwrap().text, "");
        assert_eq!(filtered_branches(&app).len(), 3);
    }

    #[test]
    fn filter_matches_project_name_across_projects() {
        let mut app = test_app(default_bindings());
        let now = Utc::now();
        let demo_id = app.engine.projects[0].id.clone();
        // A second project whose name (not branch) is the discriminating field.
        let mut website = app.engine.projects[0].clone();
        website.id = "project-website".to_string();
        website.name = "website".to_string();
        app.engine.projects.push(website);

        app.engine.sessions.clear();
        // Identical branch/title, so only the project name differs.
        app.engine
            .sessions
            .push(filter_test_session("s-demo", "feature", &demo_id, now));
        app.engine.sessions.push(filter_test_session(
            "s-web",
            "feature",
            "project-website",
            now,
        ));
        app.rebuild_left_items();

        app.open_agent_filter();
        for c in "site".chars() {
            app.agent_filter.as_mut().unwrap().insert_char(c);
        }
        app.rebuild_left_items();

        let ids: Vec<String> = app
            .left_items()
            .iter()
            .filter_map(|item| match item {
                LeftItem::Session(i) => Some(app.engine.sessions[*i].id.clone()),
                _ => None,
            })
            .collect();
        assert_eq!(ids, vec!["s-web".to_string()]);
    }

    #[test]
    fn filter_does_not_match_provider_names() {
        // Provider names ("claude", "codex", ...) are far too generic as search
        // terms, so neither the session's provider nor any tab's provider is a
        // searched field: an agent named nothing like "claude" must NOT surface
        // just because a tab runs claude. Pins the removal, in lockstep with
        // the core vector `provider_names_do_not_match` and the web's
        // "does NOT match on provider names".
        let mut app = test_app(default_bindings());
        let now = Utc::now();
        let project_id = app.engine.projects[0].id.clone();
        app.engine.sessions.clear();
        app.engine.sessions.push(filter_test_session(
            "s-codex",
            "codex-agent",
            &project_id,
            now,
        ));
        app.engine.sessions.push(filter_test_session(
            "s-plain",
            "plain-agent",
            &project_id,
            now,
        ));
        // Attach a claude tab to the first agent.
        app.engine.agent_tabs.insert(
            "tab-claude".to_string(),
            crate::model::AgentTab {
                id: "tab-claude".to_string(),
                session_id: "s-codex".to_string(),
                provider: ProviderKind::from_str("claude"),
                sort_order: 1,
                created_at: now,
            },
        );
        app.rebuild_left_items();

        app.open_agent_filter();
        for c in "claude".chars() {
            app.agent_filter.as_mut().unwrap().insert_char(c);
        }
        app.rebuild_left_items();

        // No hit: the query matched only providers, which are not searched.
        assert_eq!(filtered_branches(&app), Vec::<String>::new());
    }

    /// A filter query that matches ZERO sessions must not panic when the user
    /// navigates or presses Enter, and must leave a valid selection.
    #[test]
    fn agent_filter_zero_matches_navigation_and_enter_do_not_panic() {
        let mut app = test_app(default_bindings());
        let now = Utc::now();
        let project_id = app.engine.projects[0].id.clone();
        app.engine.sessions.clear();
        for branch in ["api", "web"] {
            app.engine.sessions.push(filter_test_session(
                &format!("session-{branch}"),
                branch,
                &project_id,
                now,
            ));
        }
        app.rebuild_left_items();
        app.focus = FocusPane::Left;
        app.left_section = LeftSection::Projects;

        app.open_agent_filter();
        for c in "zzzznomatch".chars() {
            app.handle_key(KeyEvent::new(KeyCode::Char(c), KeyModifiers::NONE))
                .unwrap();
        }
        assert!(
            filtered_branches(&app).is_empty(),
            "the query should match nothing",
        );

        // Navigation and Enter over the empty filtered list must not panic.
        app.handle_key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE))
            .unwrap();
        app.handle_key(KeyEvent::new(KeyCode::Up, KeyModifiers::NONE))
            .unwrap();
        app.handle_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();

        // The selection is still within bounds of whatever list is now showing.
        let len = app.left_items().len();
        assert!(
            len == 0 || app.selected_left < len,
            "selection {} must be valid for a list of {len}",
            app.selected_left,
        );
    }

