    #[test]
    fn agent_rows_render_two_lines_and_clicks_map_on_both() {
        use crate::model::SessionStatus;
        use ratatui::Terminal;
        use ratatui::backend::TestBackend;

        let mut app = test_app(default_bindings());
        // Two active agents: two 3-line rows (name, metadata, spacer), no Inactive
        // tail, no scroll.
        let mut second = app.engine.sessions[0].clone();
        second.id = "session-2".to_string();
        second.branch_name = "second-branch".to_string();
        second.title = None;
        app.engine.sessions.push(second);
        let ids: Vec<String> = app.engine.sessions.iter().map(|s| s.id.clone()).collect();
        for id in &ids {
            app.engine.mark_session_status(id, SessionStatus::Active);
        }
        app.focus = FocusPane::Left;
        app.rebuild_left_items();

        let backend = TestBackend::new(120, 30);
        let mut terminal = Terminal::new(backend).expect("terminal");
        terminal
            .draw(|frame| app.render(frame))
            .expect("render frame");

        // Each agent occupies three consecutive rows in the click map.
        let map = &app.mouse_layout.left_row_to_item;
        assert_eq!(map.first().copied(), Some(0), "row 0 -> agent 0");
        assert_eq!(map.get(1).copied(), Some(0), "row 1 -> agent 0");
        assert_eq!(map.get(2).copied(), Some(0), "row 2 (spacer) -> agent 0");
        assert_eq!(map.get(3).copied(), Some(1), "row 3 -> agent 1");
        assert_eq!(map.get(4).copied(), Some(1), "row 4 -> agent 1");
        assert_eq!(map.get(5).copied(), Some(1), "row 5 (spacer) -> agent 1");

        // Line one carries the name; line two carries the state word.
        let rendered: String = terminal
            .backend()
            .buffer()
            .content
            .iter()
            .map(|cell| cell.symbol())
            .collect();
        assert!(
            rendered.contains("second-branch"),
            "agent name renders on line one: {rendered}"
        );
        assert!(
            rendered.contains("Idle"),
            "state word renders on line two: {rendered}"
        );

        // A click on ANY of the second agent's three rows resolves to that agent.
        let x = app.mouse_layout.left_list.x;
        let y0 = app.mouse_layout.left_list.y;
        assert_eq!(
            app.mouse_target(x, y0 + 3),
            Some(super::MouseTarget::LeftRow(1)),
            "click on agent 1's name line",
        );
        assert_eq!(
            app.mouse_target(x, y0 + 5),
            Some(super::MouseTarget::LeftRow(1)),
            "click on agent 1's spacer line",
        );
    }

    #[test]
    fn inactive_section_auto_expands_when_all_agents_are_inactive() {
        use crate::model::SessionStatus;
        let mut app = test_app(default_bindings());
        // The fixture seeds a single Detached agent and no active ones.
        app.rebuild_left_items();
        assert!(
            !app.inactive_collapsed,
            "a wholly-inactive workspace expands the Inactive section by default",
        );

        // Add an active agent: the section auto-collapses again.
        let mut active = app.engine.sessions[0].clone();
        active.id = "active-1".to_string();
        active.status = SessionStatus::Active;
        app.engine.sessions.push(active);
        app.rebuild_left_items();
        assert!(
            app.inactive_collapsed,
            "an active agent collapses the Inactive tail",
        );

        // A manual toggle takes over and sticks across rebuilds.
        app.toggle_collapse_selected_project();
        assert!(app.inactive_collapse_overridden);
        let after = app.inactive_collapsed;
        app.rebuild_left_items();
        assert_eq!(
            app.inactive_collapsed, after,
            "a manual toggle overrides the auto-manage",
        );
    }

    #[test]
    fn selected_agent_gets_tinted_frame() {
        use crate::model::SessionStatus;
        use ratatui::Terminal;
        use ratatui::backend::TestBackend;

        let mut app = test_app(default_bindings());
        let mut second = app.engine.sessions[0].clone();
        second.id = "session-2".to_string();
        second.branch_name = "second-branch".to_string();
        app.engine.sessions.push(second);
        for id in app
            .engine
            .sessions
            .iter()
            .map(|s| s.id.clone())
            .collect::<Vec<_>>()
        {
            app.engine.mark_session_status(&id, SessionStatus::Active);
        }
        app.focus = FocusPane::Left;
        app.left_section = LeftSection::Projects;
        app.rebuild_left_items();
        // Select the SECOND agent: its name/meta/spacer land on rows 3/4/5.
        app.selected_left = app
            .left_items()
            .iter()
            .position(|i| matches!(i, LeftItem::Session(idx) if *idx == 1))
            .expect("second agent row");

        let backend = TestBackend::new(120, 30);
        let mut terminal = Terminal::new(backend).expect("terminal");
        terminal
            .draw(|frame| app.render(frame))
            .expect("render frame");

        let buf = terminal.backend().buffer();
        let gx = app.mouse_layout.left_list.x; // the left gutter column
        let x1 = gx + app.mouse_layout.left_list.width; // one past the right edge
        let y0 = app.mouse_layout.left_list.y;
        let tint = app.theme.selection_bar_tint();
        // No accent bar: the left gutter is now a plain tinted pad, not a `▌`.
        assert_ne!(buf[(gx, y0 + 3)].symbol(), "▌", "no bar on the name row");
        assert_ne!(
            buf[(gx, y0 + 4)].symbol(),
            "▌",
            "no bar on the metadata row"
        );
        // The tint fills the content rows edge to edge, both gutters included, so
        // the selection is a clean tinted band with equal left and right padding.
        for x in [gx, gx + 1, x1 - 2, x1 - 1] {
            assert_eq!(buf[(x, y0 + 3)].bg, tint, "name row cell {x} is tinted");
            assert_eq!(buf[(x, y0 + 4)].bg, tint, "metadata row cell {x} is tinted");
        }
        // ...framed by half-cell edges: a `▄` top edge on the row above (agent 0's
        // spacer) and a `▀` bottom edge on this agent's trailing spacer, painted in
        // the tint (the selection background extended a half-cell), not the accent.
        assert_eq!(buf[(gx + 1, y0 + 2)].symbol(), "▄", "top frame edge");
        assert_eq!(buf[(gx + 1, y0 + 5)].symbol(), "▀", "bottom frame edge");
        assert_eq!(buf[(gx + 1, y0 + 2)].fg, tint, "top edge is the tint");
        assert_eq!(buf[(gx + 1, y0 + 5)].fg, tint, "bottom edge is the tint");
    }

