    fn viewport_contains(client: &crate::pty::PtyClient, needle: &str) -> bool {
        let snap = client.snapshot();
        let mut rows: Vec<String> = vec![String::new(); usize::from(snap.rows)];
        for cell in &snap.cells {
            if let Some(row) = rows.get_mut(usize::from(cell.row)) {
                row.push_str(&cell.symbol);
            }
        }
        rows.iter().any(|r| r.contains(needle))
    }

    /// Minimizing (Ctrl-g) while scrolled back must snap the PTY to the live
    /// edge. Scrolling back moves the display offset, and the terminal library
    /// holds that view still as new lines arrive, so an offset left behind on
    /// exit froze the minimized pane on stale content (the grid kept updating,
    /// but nothing new was VISIBLE until a later scroll walked the offset back
    /// to the bottom). Entering interactive mode already snaps to the live
    /// edge, so exiting must too.
    #[test]
    fn exit_interactive_while_scrolled_back_snaps_to_the_live_edge() {
        let mut app = test_app(default_bindings());
        let client = crate::pty::PtyClient::spawn(
            "sh",
            &["-c".to_string(), "cat".to_string()],
            std::path::Path::new("."),
            10,
            40,
            1000,
        )
        .expect("spawn pty");
        // Fill enough history that scrolling back 20 rows is possible.
        let mut fill = String::new();
        for i in 0..60 {
            fill.push_str(&format!("line {i}\n"));
        }
        client.write_bytes(fill.as_bytes()).expect("write fill");
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(8);
        while !viewport_contains(&client, "line 59") {
            assert!(std::time::Instant::now() < deadline, "fill never echoed");
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        app.engine.providers.insert("session-1".to_string(), client);
        app.focus = FocusPane::Center;
        app.center_mode = CenterMode::Agent;
        app.input_target = InputTarget::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        // The user wheel-scrolled up to read history: the view stops tracking
        // the live edge.
        let provider = app.engine.providers.get("session-1").expect("provider");
        provider.set_scrollback(20);
        assert_eq!(provider.scrollback_offset(), 20, "scrolled back");

        app.exit_interactive_mode();

        let provider = app.engine.providers.get("session-1").expect("provider");
        assert_eq!(
            provider.scrollback_offset(),
            0,
            "exiting interactive mode must snap the PTY to the live edge"
        );
        // And the view must be tracking the live edge again, which is what
        // `viewport_contains` measures: it reads the offset-relative snapshot,
        // so it only sees the marker if the pane is showing the bottom.
        provider
            .write_bytes(b"marker-after-exit\n")
            .expect("write marker");
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(8);
        while !viewport_contains(
            app.engine.providers.get("session-1").expect("provider"),
            "marker-after-exit",
        ) {
            assert!(
                std::time::Instant::now() < deadline,
                "new PTY output never became visible in the minimized pane: \
                 the scrollback offset was left behind on exit"
            );
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    #[test]
    fn exit_interactive_from_terminal_overlay_resets_state() {
        let mut app = test_app(default_bindings());

        app.show_companion_terminal()
            .expect("launch companion terminal");

        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::Terminal);
        assert_eq!(app.input_target, InputTarget::Terminal);

        // Simulate ExitInteractive via the raw input path: feed Ctrl-g
        // (0x07) into the raw input buffer and process sequences.
        app.raw_input_buf = vec![0x07];
        let (sequences, _) = crate::raw_input::split_sequences(&app.raw_input_buf);
        assert_eq!(sequences.len(), 1);
        let matched = app.interactive_patterns.match_sequence(sequences[0]);
        assert_eq!(matched, Some((Action::ExitInteractive, false)));

        // Apply the same state change that poll_and_forward_raw_input does.
        let return_to_list =
            matches!(app.input_target, InputTarget::Terminal) && app.terminal_return_to_list;
        app.input_target = InputTarget::None;
        app.fullscreen_overlay = FullscreenOverlay::None;
        app.session_surface = SessionSurface::Agent;
        app.raw_input_buf.clear();
        if return_to_list {
            app.left_section = LeftSection::Terminals;
            app.focus = FocusPane::Left;
        }

        // Launched via `t` → returns to terminals list on the left pane.
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::None);
        assert_eq!(app.session_surface, SessionSurface::Agent);
        assert_eq!(app.input_target, InputTarget::None);
        assert_eq!(app.left_section, LeftSection::Terminals);
        assert_eq!(app.focus, FocusPane::Left);
    }

    /// Minimizing a MULTI-TAB agent leaves focus on the pane you were in.
    ///
    /// Jumping to the sidebar made the Center-scope tab keys dead the instant
    /// you minimized, with nothing on screen explaining why. The sidebar still
    /// SNAPS to Projects so the agent you are looking at is the visible
    /// selection, but it does not steal focus to do it. A single-tab agent
    /// keeps the original behaviour; see the test below.
    #[test]
    fn exit_interactive_from_a_multi_tab_agent_keeps_focus_on_the_agent_pane() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        seed_input_tab(&mut app, &session_id, "tab-2", "claude", 1);
        app.focus = FocusPane::Center;
        app.left_section = LeftSection::Terminals;
        app.input_target = InputTarget::Agent;
        app.session_surface = SessionSurface::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        app.process_raw_input_bytes(&[0x07]).unwrap();

        assert_eq!(app.input_target, InputTarget::None);
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::None);
        assert_eq!(app.session_surface, SessionSurface::Agent);
        assert_eq!(app.left_section, LeftSection::Projects);
        assert_eq!(
            app.focus,
            FocusPane::Center,
            "minimizing must not move focus off the pane the user was in"
        );
    }

    /// A SINGLE-tab agent still returns to Projects on minimize.
    ///
    /// This is the pre-existing behaviour, kept deliberately: with no tab
    /// strip on screen there is nothing to switch between, so the Center-scope
    /// tab keys buy nothing and the older habit of landing back in the agent
    /// list is the more useful one.
    #[test]
    fn exit_interactive_from_a_single_tab_agent_returns_to_projects() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        assert_eq!(
            app.session_tab_ids(&session_id).len(),
            1,
            "the fixture must be a single-tab agent or this proves nothing"
        );
        app.focus = FocusPane::Center;
        app.left_section = LeftSection::Terminals;
        app.input_target = InputTarget::Agent;
        app.session_surface = SessionSurface::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        app.process_raw_input_bytes(&[0x07]).unwrap();

        assert_eq!(app.left_section, LeftSection::Projects);
        assert_eq!(
            app.focus,
            FocusPane::Left,
            "a single-tab agent keeps returning to the agent list"
        );
    }

    /// The focus rule reads the TAB COUNT, not whether the strip is drawn.
    ///
    /// `ui.always_show_tab_strip` puts the strip on screen for a single-tab
    /// agent. If the rule keyed off the strip, turning that preference on
    /// would silently start holding focus on the center pane for an agent with
    /// nothing to switch to. A display preference must not move the keyboard.
    #[test]
    fn always_showing_the_tab_strip_does_not_change_where_focus_lands() {
        let mut app = test_app(default_bindings());
        app.engine.config.ui.always_show_tab_strip = true;
        let session_id = app.engine.sessions[0].id.clone();
        assert_eq!(
            app.session_tab_ids(&session_id).len(),
            1,
            "the fixture must be a single-tab agent or this proves nothing"
        );
        app.focus = FocusPane::Center;
        app.input_target = InputTarget::Agent;
        app.session_surface = SessionSurface::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        app.exit_interactive_mode();

        assert_eq!(
            app.focus,
            FocusPane::Left,
            "one tab is one tab, however the strip is configured to render"
        );
    }

    /// The Center-scope tab keys are reachable straight after minimizing.
    ///
    /// This is the concrete cost of the old focus jump: the tab keys are
    /// Center-scope, so landing on the sidebar meant neither the Ctrl arrows
    /// nor the plain ones did anything until you Tab-ed back.
    #[test]
    fn a_tab_key_works_immediately_after_minimizing_an_agent() {
        let mut app = test_app(default_bindings());
        let session_id = app.engine.sessions[0].id.clone();
        seed_input_tab(&mut app, &session_id, "tab-2", "claude", 1);
        app.center_mode = CenterMode::Agent;
        app.focus = FocusPane::Center;
        app.input_target = InputTarget::Agent;
        app.session_surface = SessionSurface::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        app.exit_interactive_mode();
        app.handle_key(KeyEvent::new(KeyCode::Right, KeyModifiers::NONE))
            .expect("handle arrow");

        assert_eq!(
            app.focused_tab_id(&session_id),
            "tab-2",
            "the tab key must land without a detour through the sidebar"
        );
    }

    #[test]
    fn custom_exit_interactive_key_reopens_a_minimized_agent() {
        let bindings = bindings_with_overrides(&[(Action::ExitInteractive, &["home"])]);
        let mut app = test_app(bindings);
        let session_id = app.engine.sessions[0].id.clone();
        app.engine.providers.insert(
            session_id,
            PtyClient::spawn(
                "sh",
                &["-c".to_string(), "printf ready; sleep 0.2".to_string()],
                std::path::Path::new("."),
                10,
                10,
                100,
            )
            .expect("spawn pty"),
        );

        app.focus = FocusPane::Center;
        app.input_target = InputTarget::Agent;
        app.session_surface = SessionSurface::Agent;
        app.fullscreen_overlay = FullscreenOverlay::Agent;

        app.process_raw_input_bytes(b"\x1b[H").unwrap();

        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::None);
        assert_eq!(app.left_section, LeftSection::Projects);
        assert_eq!(
            app.focus,
            FocusPane::Left,
            "single-tab agent, so this one still lands in the agent list"
        );

        // The two-way toggle re-enters from wherever focus landed. Pinned from
        // the sidebar here; the multi-tab path leaves focus on the center pane
        // and re-enters through the same activation, which is why dropping the
        // focus steal there was safe.
        app.handle_key(KeyEvent::new(KeyCode::Home, KeyModifiers::NONE))
            .unwrap();

        assert_eq!(app.input_target, InputTarget::Agent);
        assert_eq!(app.fullscreen_overlay, FullscreenOverlay::Agent);
        assert_eq!(app.focus, FocusPane::Center);
    }

